const weather=document.getElementById("weather");async function loadWeather(){try{const e=await fetch("https://api.open-meteo.com/v1/forecast?latitude=51.05&longitude=-114.07&current=temperature_2m,wind_speed_10m",{signal:AbortSignal.timeout(7e3)});if(!e.ok)throw new Error("Weather unavailable");const t=await e.json(),a=t.current.temperature_2m,n=t.current.wind_speed_10m;if(!Number.isFinite(a)||!Number.isFinite(n))throw new Error("Invalid weather data");weather.textContent=`Temperature: ${a}°C | Wind: ${n} km/h`}catch{weather.textContent="Weather unavailable. Please try again later."}}loadWeather();const mapButton=document.getElementById("loadMap"),map=document.getElementById("trailMap");mapButton.addEventListener("click",(()=>{map.src=map.dataset.src,map.hidden=!1,mapButton.remove()}));